package com.affilemanager.app.security

import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.File
import java.security.MessageDigest
import java.util.Base64

class LegacyVaultCompatibilityTest {
    @get:Rule val temporary = TemporaryFolder()

    // Captured from frozen baseline APK 58B1E745... on API36, not generated by the V2 code.
    @Test fun theActualOldAndroidWriterRemainsReadableWithoutRewritingTheVault() = runBlocking {
        val vector = javaClass.getResourceAsStream("/affmv1-legacy-vector.b64")!!.use { Base64.getDecoder().decode(it.reader().readText().trim()) }
        assertEquals("5a2cfb10b4c6244794f82170ea201c07468df57676d4df406426cb864931c60a",
            MessageDigest.getInstance("SHA-256").digest(vector).joinToString("") { "%02x".format(it) })
        val vault = temporary.newFile("legacy.afvault").apply { writeBytes(vector) }
        val engine = FileVaultEngine()
        assertEquals(VaultHeader("legacy.txt", 55, 1), engine.inspect(vault))
        val output = engine.decrypt(vault, temporary.newFolder("output"), "public-compatibility-vector".toCharArray())
        assertEquals("AF legacy compatibility ąčęėįšųūž\nsecond line\n", output.readText())
        assertArrayEquals(vector, vault.readBytes())
    }

    @Test fun wrongLegacyPassphraseDoesNotPublishOrLeaveTemporaryPlaintext() = runBlocking {
        val vector = javaClass.getResourceAsStream("/affmv1-legacy-vector.b64")!!.use { Base64.getDecoder().decode(it.reader().readText().trim()) }
        val vault = temporary.newFile("legacy.afvault").apply { writeBytes(vector) }
        val output = temporary.newFolder("output")
        assertTrue(runCatching { FileVaultEngine().decrypt(vault, output, "wrong-passphrase".toCharArray()) }.isFailure)
        assertTrue(output.list()!!.isEmpty())
        assertArrayEquals(vector, vault.readBytes())
    }
}
